from playwright.sync_api import sync_playwright
import tkinter as tk
from itertools import product

def fetch_yinyang(url="https://www.puzzle-yinyang.com/"):
    """
    输入阴阳网页链接（支持每日、每月或任意尺寸页面），
    后台静默抓取并直接返回 (size, grid)
    - size: 正方形尺寸 (int)
    - grid: 2D 矩阵 (0: 白子, 1: 黑子, None: 空白)
    """
    print(f"正在后台启动无头浏览器抓取阴阳页面: {url} ...")
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        page.goto(url)

        # 核心等待：等棋盘所有格子渲染完毕
        page.wait_for_selector(".task-cell, .cell.selectable")

        data = page.evaluate("""() => {
            let cells = Array.from(document.querySelectorAll('.task-cell, .cell.selectable'));
            if (!cells.length) {
                cells = Array.from(document.querySelectorAll('.cell'));
            }

            cells.sort((a, b) => {
                let topDiff = a.offsetTop - b.offsetTop;
                if (Math.abs(topDiff) > 5) return topDiff;
                return a.offsetLeft - b.offsetLeft;
            });

            let size = Math.round(Math.sqrt(cells.length));
            let grid = [];

            for (let r = 0; r < size; r++) {
                let row = [];
                for (let c = 0; c < size; c++) {
                    let el = cells[r * size + c];
                    if (el.classList.contains('cell-0')) {
                        row.push(0); // 白子
                    } else if (el.classList.contains('cell-1')) {
                        row.push(1); // 黑子
                    } else {
                        row.push(-1); // 空白
                    }
                }
                grid.push(row);
            }

            return { size: size, grid: grid };
        }""")

        browser.close()
        print(f"✔ 抓取成功！识别尺寸: {data['size']}x{data['size']}")
        return data["size"], data["grid"]

def show_yinyang(size, grid):
    """
    阴阳棋盘可视化器（支持超大棋盘自由拖拽平移、滚轮漫游防爆屏版）
    :param size: 正方形棋盘边长 (int)
    :param grid: 2D 矩阵 (0: 白子, 1: 黑子, -1: 未确定空位)
    """
    root = tk.Tk()
    root.title(f"Yin-Yang Visualization ({size}x{size}) - [按住鼠标任意键可自由拖动画布]")

    # 1. 获取用户物理屏幕分辨率，防止窗口过大撑爆屏幕
    screen_w = root.winfo_screenwidth()
    screen_h = root.winfo_screenheight()

    # 格子大小（保持舒适清晰度）
    cell_size = max(24, min(36, 800 // size)) if size <= 20 else 26
    margin_x = 45
    margin_y = 45

    # 实际整个棋盘的总画布物理像素
    total_w = margin_x * 2 + cell_size * size
    total_h = margin_y * 2 + cell_size * size

    # 窗口可视区域尺寸（限制在屏幕的 82% 范围内）
    view_w = min(total_w + 30, int(screen_w * 0.82))
    view_h = min(total_h + 30, int(screen_h * 0.82))

    # 居中显示窗口
    pos_x = (screen_w - view_w) // 2
    pos_y = (screen_h - view_h) // 2
    root.geometry(f"{view_w}x{view_h}+{pos_x}+{pos_y}")

    # 2. 创建带滚动区域（Scrollregion）的画布
    frame = tk.Frame(root)
    frame.pack(fill=tk.BOTH, expand=True)

    canvas = tk.Canvas(
        frame,
        bg="#2B2B2B",  # 视窗外边框深灰底色，反衬棋盘
        scrollregion=(0, 0, total_w, total_h)
    )

    # 3. 增加水平和垂直滚动条（备用）
    h_bar = tk.Scrollbar(frame, orient=tk.HORIZONTAL, command=canvas.xview)
    v_bar = tk.Scrollbar(frame, orient=tk.VERTICAL, command=canvas.yview)
    canvas.configure(xscrollcommand=h_bar.set, yscrollcommand=v_bar.set)

    h_bar.pack(side=tk.BOTTOM, fill=tk.X)
    v_bar.pack(side=tk.RIGHT, fill=tk.Y)
    canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

    # ================= 核心：原生极速鼠标拖拽漫游 =================
    def on_drag_start(event):
        canvas.scan_mark(event.x, event.y)

    def on_drag_move(event):
        canvas.scan_dragto(event.x, event.y, gain=1)

    # 绑定左键、右键、中键均可拖拽！
    for btn in ("<ButtonPress-1>", "<ButtonPress-2>", "<ButtonPress-3>"):
        canvas.bind(btn, on_drag_start)
    for motion in ("<B1-Motion>", "<B2-Motion>", "<B3-Motion>"):
        canvas.bind(motion, on_drag_move)

    # 绑定鼠标滚轮 (Windows / Linux)
    canvas.bind("<MouseWheel>", lambda e: canvas.yview_scroll(int(-1 * (e.delta / 120)), "units"))
    canvas.bind("<Shift-MouseWheel>", lambda e: canvas.xview_scroll(int(-1 * (e.delta / 120)), "units"))

    # ================= 绘制棋盘实体内容 =================
    COLOR_BOARD = "#D4A359"
    COLOR_LINE  = "#5A3D1E"

    board_x1 = margin_x
    board_y1 = margin_y
    board_x2 = margin_x + size * cell_size
    board_y2 = margin_y + size * cell_size

    # 木纹棋盘底色
    canvas.create_rectangle(
        board_x1, board_y1, board_x2, board_y2,
        fill=COLOR_BOARD, outline=COLOR_LINE, width=2
    )

    # 网格线
    for i in range(size + 1):
        y = margin_y + i * cell_size
        canvas.create_line(board_x1, y, board_x2, y, fill=COLOR_LINE, width=1)
        x = margin_x + i * cell_size
        canvas.create_line(x, board_y1, x, board_y2, fill=COLOR_LINE, width=1)

    # 棋子
    radius = cell_size * 0.38
    highlight_r = max(1.5, radius * 0.22)

    for r in range(size):
        for c in range(size):
            val = grid[r][c]
            if val == -1:
                continue

            cx = margin_x + c * cell_size + cell_size / 2
            cy = margin_y + r * cell_size + cell_size / 2

            if val == 1:
                # 黑子 (饱满深黑 + 立体微高光)
                canvas.create_oval(
                    cx - radius, cy - radius, cx + radius, cy + radius,
                    fill="#1A1A1A", outline="#000000", width=1.2
                )
                canvas.create_oval(
                    cx - radius * 0.35 - highlight_r, cy - radius * 0.35 - highlight_r,
                    cx - radius * 0.35 + highlight_r, cy - radius * 0.35 + highlight_r,
                    fill="#666666", outline=""
                )
            elif val == 0:
                # 白子 (温润纯白 + 浅灰立体外圈)
                canvas.create_oval(
                    cx - radius, cy - radius, cx + radius, cy + radius,
                    fill="#FDFDFD", outline="#A0A0A0", width=1.5
                )

    # 四周坐标文字 (a..ad, 1..30)
    font_coord = ("Arial", max(8, int(cell_size * 0.38)), "bold")
    for i in range(size):
        col_letter = chr(ord('a') + i) if i < 26 else f"a{chr(ord('a') + i - 26)}"
        cx = margin_x + i * cell_size + cell_size / 2

        canvas.create_text(cx, margin_y - 18, text=col_letter, font=font_coord, fill="#7A6040")
        canvas.create_text(cx, margin_y + size * cell_size + 18, text=col_letter, font=font_coord, fill="#7A6040")

        cy = margin_y + i * cell_size + cell_size / 2
        canvas.create_text(margin_x - 18, cy, text=str(i + 1), font=font_coord, fill="#7A6040")
        canvas.create_text(margin_x + size * cell_size + 18, cy, text=str(i + 1), font=font_coord, fill="#7A6040")

    root.mainloop()

