def count_blank(grid):
    result=0
    for i in grid:
        for j in i:
            if j==-1:
                result+=1
    return result

def find_neig4(y,x):
    result=[]
    for i,j in [(y+1,x),(y-1,x),(y,x+1),(y,x-1)]:
        if 0<=i<size and 0<=j<size:
            result.append((i,j))
    return result

def find_neig8(y,x):
    result=[]
    for i,j in [(y+1,x),(y-1,x),(y,x+1),(y,x-1),(y+1,x+1),(y-1,x-1),(y-1,x+1),(y+1,x-1)]:
        if 0<=i<size and 0<=j<size:
            result.append((i,j))
    return result

def rightdowntian(y,x):#右下田，本-右-下-右下
    return [(y,x),(y,x+1),(y+1,x),(y+1,x+1)]

def equalpattern(formwork,corner):#生成旋转+翻转+换色最多16种不同方案
    def rotate(formwork):#全部顺时针转90度
        for i in range(len(formwork)):
            formwork[i]=(formwork[i][1],corner[0]-formwork[i][0],formwork[i][2])
    def overturn(formwork):#翻转
        for i in range(len(formwork)):
            formwork[i]=(corner[0]-formwork[i][0],formwork[i][1],formwork[i][2])
    def res(formwork):#换色
        for i in range(len(formwork)):
            formwork[i]=(formwork[i][0],formwork[i][1],{1:0,0:1,-1:-1}[formwork[i][2]])
    formwork1=formwork[0]+[formwork[1]]#实际使用的
    result=[]
    for _ in range(4):
        for _ in range(2):
            result.append([formwork1[0:-1],formwork1[-1],corner])
            res(formwork1)
            result.append([formwork1[0:-1],formwork1[-1],corner])
            overturn(formwork1)
        rotate(formwork1)
        corner=(corner[1],corner[0])
    return result

