#不涉及基本参数修改，没必要包装成main函数
def pattern_matching(a,b,n=None,grid=grid):#这期神了
    if len(a)!=len(b):
        raise NotMatchError(f'pattern_matching,{a},{b}')
    a1=[]
    b1=[]
    for i in a:
        a1.append(grid[i[0]][i[1]])
    b1=list(b)
    diffcount=0
    diff=[]
    for i in range(len(a)):
        if a1[i]!=b1[i]:
            diffcount+=1
            diff.append([a[i],b1[i]])
    if n is None:
        return diffcount
    else:
        return diff

