blank=count_blank(grid)
last_blank=size**2
while last_blank>blank:
    last_blank=blank

    for y, x in product(range(size-1), range(size-1)):#是否有禁止田：全黑、全白、两种国际象棋
        if (y,x) not in successtian:
            structure=rightdowntian(y,x)
            unknown=0
            for i in structure:
                if grid[i[0]][i[1]]==-1:
                    unknown+=1
            if unknown==1:
                for i in ((1,1,1,1),(0,0,0,0),(1,0,0,1),(0,1,1,0)):
                    if pattern_matching(structure,i)==1:
                        bian=pattern_matching(structure,i,1)[0]
                        grid[bian[0][0]][bian[0][1]]=1-bian[1]
                        break
            if unknown==0:
                for i in ((1,1,1,1),(0,0,0,0),(1,0,0,1),(0,1,1,0)):
                    if pattern_matching(structure,i)==0:
                        raise MaodunError('禁忌田！')
                successtian.add((y,x))

    for y, x in product(range(size-1), range(size-1)):#所有结构之力
        for lo,goal,maxxx in Allstru:
            if y+maxxx[0]>=size or x+maxxx[1]>=size:
                continue
            if grid[y+goal[0]][x+goal[1]]!=-1:
                continue
            for dr, dc, required in lo:
                if grid[y + dr][x + dc] != required:
                    break
            else:
                grid[y + goal[0]][x + goal[1]] = goal[2]
    #连通部分
    liantong4=[]
    #1、现有格子加入liantong系列，不包括-1
    visited=set()
    for y, x in product(range(size), range(size)):
        if (y,x) not in visited and grid[y][x]!=-1:
            zu=grid[y][x]
            now=[set(),set(),zu]
            boundry=set()
            boundry.add((y,x))
            while boundry:
                lo=boundry.pop()
                if grid[lo[0]][lo[1]]!=zu:
                    now[1].add(lo)
                else:
                    now[0].add(lo)
                    boundry.update(set([i for i in find_neig4(*lo) if i not in now[0]]))
            visited.update(now[0])
            liantong4.append(now)


    '''
    冲破封锁：
    1、外界-1全部相反，只有一个未知，则这个未知被同化（最主要）
    2、外界全部相反，报错
    3、一个-1周围全是同色，同化（不可能有多个-1被包围，因为这一定会造成2*2错误）
    '''
    for i in liantong4:
        zu=i[2]
        kind=list(map(lambda x:grid[x[0]][x[1]],i[1]))
        if set(kind)=={1-zu}:#外界全部和自己相反？
            #首先，如果已经全部完成了，那就正常
            finish=count_blank(grid)
            if finish==0:
                print('结束了！')
                break
            raise SurroundError('孤岛！')
        else:#触发规则1：统计外圈-1的个数
            situation=None#故技重施
            for j in i[1]:#j是外围的每一个坐标
                if grid[j[0]][j[1]]!=1-zu:
                    if situation is None:
                        situation=j
                    else:
                        situation=None
                        break
            if situation is not None:
                grid[situation[0]][situation[1]]=zu
    for y, x in product(range(1,size-1), range(1,size-1)):#1
        for i in ((1,1,1,1),(0,0,0,0)):
            if pattern_matching(find_neig4(y,x),i)==0:#这个-1已经被包围了！
                grid[y][x]=i[0]
                break
    '''
    防止闭合：八连通两不相邻格共同被-1相邻，则考察这两个格子的连通距离，若小于某个值则说明即将闭合，-1必须相反
    '''
    liantong8=[]
    liantong8dict={}
    order=0
    #现有格子加入liantong8系列，不包括-1
    visited=set()
    for y, x in product(range(size), range(size)):
        if (y,x) not in visited and grid[y][x]!=-1:
            zu=grid[y][x]
            now=[set(),set(),zu]
            boundry=set()
            boundry.add((y,x))
            while boundry:
                lo=boundry.pop()
                if grid[lo[0]][lo[1]]!=zu:
                    now[1].add(lo)
                else:
                    now[0].add(lo)
                    liantong8dict[lo]=order
                    boundry.update(set([i for i in find_neig8(*lo) if i not in now[0]]))
            visited.update(now[0])
            liantong8.append(now)
            order+=1
        elif grid[y][x]==-1:
            liantong8dict[(y,x)]=float('nan')
    #开始！
    for y, x in product(range(size), range(size)):
        if grid[y][x]!=-1:
            continue
        
        for (dy1, dx1), (dy2, dx2), k_max in neipairs:#最大可接受距离为3
            p1 = (y + dy1, x + dx1)
            p2 = (y + dy2, x + dx2) 
            if not (0 <= p1[0] < size and 0 <= p1[1] < size and 0 <= p2[0] < size and 0 <= p2[1] < size):
                continue#有出界格
            zu=liantong8dict[p1]
            if zu==liantong8dict[p2]:#来看看i[0]多久可以到i[1]吧
                nei={p1}
                for _ in range(k_max+1):
                    for a in nei.copy():
                        for b in find_neig8(*a):
                            if liantong8dict[b]==zu:
                                nei.add(b)
                if p2 not in nei:
                    grid[y][x]=1-grid[p1[0]][p1[1]]
                    break

    #外围特殊处理；可证明：外围不能出现间断的黑或白；采用四库全书处理，人也可以这么干
    outzhi=[grid[i[0]][i[1]] for i in out]
    for i in range(len(outzhi)):
        if outzhi[i]==1:
            bigset=[j for j in bigset if (j[0] <= i) + (i < j[1]) + (j[1] < j[0]) == 2]
        elif outzhi[i]==0:
            bigset=[j for j in bigset if (j[0] <= i) + (i < j[1]) + (j[1] < j[0]) == 1]
    #逐个代入……这不能叫回溯吧，只是尝试；原来的外圈储存在outzhi里
    dellist=[]
    for j in bigset:#每种情况
        for i in range(len(out)):#导入
            if (j[0] <= i) + (i < j[1]) + (j[1] < j[0]) == 2:
                grid[out[i][0]][out[i][1]]=1
            else:
                grid[out[i][0]][out[i][1]]=0
        try:
            for lo in outtest:#照搬前面的田字格代码，删掉多余部分
                if lo not in successtian:
                    structure=rightdowntian(*lo)
                    unknown=0
                    for i in structure:
                        if grid[i[0]][i[1]]==-1:
                            unknown+=1
                    if unknown==0:
                        for i in ((1,1,1,1),(0,0,0,0),(1,0,0,1),(0,1,1,0)):
                            if pattern_matching(structure,i)==0:
                                raise MaodunError('禁忌田！')
        except MaodunError:
            dellist.append(j)
    for i in dellist:
        bigset.remove(i)
    #甚至没必要复原，因为最后票数不全的都回到-1了
    # 对外圈的每一个格子，统计幸存方案在这一格上的共识
    for i in range(len(out)):
        if outzhi[i] != -1:
            continue # 已确定的不用看
            
        # 测一下剩下的方案里，有几个认为第 i 格是黑色
        black_votes = 0
        for j in bigset:
            is_black = (j[0] <= i) + (i < j[1]) + (j[1] < j[0]) == 2
            if is_black:
                black_votes += 1
                
        # 1. 所有幸存方案全票通过是黑色 -> 锁定为黑！
        if black_votes == len(bigset):
            grid[out[i][0]][out[i][1]] = 1
        # 2. 没有任何方案认为是黑色 -> 锁定为白！
        elif black_votes == 0:
            grid[out[i][0]][out[i][1]] = 0
        else:
            grid[out[i][0]][out[i][1]] = -1


    
    blank=count_blank(grid)
    print(blank)


show_yinyang(size, grid)